<template>
  <v-card class="image-slider">
    <v-carousel
      :continuous="true"
      :show-arrows="true"
      :cycle="autoPlay"
      interval="3000"
      height="auto"
      hide-delimiter-background
      delimiter-icon="mdi-circle"
      v-model="currentSlide"
    >
      <v-carousel-item
        v-for="(image, index) in images"
        :key="index"
        @click="handleImageClick(image)"
      >
        <v-img
          :src="image.url"
          :alt="image.alt"
          :aspect-ratio="16/9"
          class="align-end"
          contain
        >
          <template v-if="showCaptions" v-slot:placeholder>
            <v-row class="fill-height ma-0" align="center" justify="center">
              <v-progress-circular indeterminate color="primary"></v-progress-circular>
            </v-row>
          </template>

          <!-- Image Caption -->
          <v-card-title v-if="showCaptions" class="text-white pb-2 pt-0 caption-overlay">
            {{ image.caption }}
          </v-card-title>

          <!-- Image Description -->
          <v-card-subtitle v-if="image.description" class="text-white pb-4 pt-0 description-overlay">
            {{ image.description }}
          </v-card-subtitle>
        </v-img>
      </v-carousel-item>
    </v-carousel>

    <v-card-actions v-if="showControls" class="controls-overlay">
      <v-spacer></v-spacer>
      <v-btn icon @click="prevSlide" :disabled="currentSlide === 0" color="white">
        <v-icon>mdi-chevron-left</v-icon>
      </v-btn>
      <v-btn icon @click="toggleAutoPlay" color="white">
        <v-icon>{{ autoPlay ? 'mdi-pause' : 'mdi-play' }}</v-icon>
      </v-btn>
      <v-btn icon @click="nextSlide" :disabled="currentSlide === images.length - 1" color="white">
        <v-icon>mdi-chevron-right</v-icon>
      </v-btn>
      <v-spacer></v-spacer>
    </v-card-actions>
  </v-card>
</template>

<script>
export default {
  name: 'ImageSlider',
  props: {
    images: {
      type: Array,
      required: true,
      validator: (value) => {
        return value.every(image => 
          typeof image === 'object' && 
          'url' in image && 
          'alt' in image &&
          'caption' in image && 
          'description' in image
        )
      }
    },
    showCaptions: {
      type: Boolean,
      default: true
    },
    showControls: {
      type: Boolean,
      default: true
    },
    defaultAutoPlay: {
      type: Boolean,
      default: true
    }
  },
  data() {
    return {
      currentSlide: 0,
      autoPlay: this.defaultAutoPlay,
    }
  },
  methods: {
    nextSlide() {
      if (this.currentSlide < this.images.length - 1) {
        this.currentSlide++
      } else {
        this.currentSlide = 0
      }
    },
    prevSlide() {
      if (this.currentSlide > 0) {
        this.currentSlide--
      } else {
        this.currentSlide = this.images.length - 1
      }
    },
    toggleAutoPlay() {
      this.autoPlay = !this.autoPlay
    },
    handleImageClick(image) {
      this.$emit('image-click', image)
    }
  }
}
</script>

<style scoped>
.image-slider {
  position: relative;
  width: 100%;
}

.controls-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.5));
  z-index: 1;
}

.caption-overlay, .description-overlay {
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  width: 100%;
}

:deep(.v-carousel__controls) {
  background: transparent;
}
</style>
