<template>
  <v-btn dense @click="renumberProjects()" color="primary" class="small-btn">Sort</v-btn>
  <v-btn dense @click="openDialog0()" color="primary" class="small-btn">Add Projects</v-btn>
  <v-container>
    <v-toolbar color="green" dark>
      <v-toolbar-title>Paste Project Listings</v-toolbar-title>
    </v-toolbar>

    <v-data-table :headers="headers" :items="projects" style="width: 100%" class="elevation-1 custom-header-table">



      <template v-slot:item="{ item, index }">
        <tr @click="selectRow(index)"
          :class="{ 'odd-row': index % 2 === 1, 'even-row': index % 2 === 0, 'highlighted-row': selectedRow === index }">


          <td class="button-container">
            <v-btn dense @click="openDialog1(item.id)" color="primary" class="small-btn">P1</v-btn>
            <v-btn dense @click="openDialog2(item.id)" color="primary" class="small-btn">P2</v-btn>
            <v-btn dense @click="openDialog3(item.id)" color="primary" class="small-btn">P3</v-btn>
          </td>

          <td>{{ item.no }}</td>
          <td>{{ item.projectName }}</td>
          <td>{{ item.projectType }}</td>
          <td>{{ item.location }}</td>
          <td>{{ item.eumPicName }}</td>
          <td>{{ item.eumPicContact }}</td>
          <td>{{ item.branch }}</td>
          <td>{{ item.agentComm }}</td>
          <td>{{ item.advanceComm }}</td>
          <td>{{ item.rebate }}</td>
          <td>{{ item.status }}</td>
          <td>{{ item.title }}</td>
          <td>{{ item.tenure }}</td>
          <td>{{ item.priceRange }}</td>
          <td>{{ item.sizeRange }}</td>
          <td>{{ item.totalUnit }}</td>

          <td>{{ item.totalStorey }}</td>
          <td>{{ item.contractStartDate }}</td>
          <td>{{ item.contractExpiryDate }}</td>

          <td>{{ item.completionDate }}</td>
          <td>{{ item.developer }}</td>

          <td>{{ item.id }}</td>


        </tr>
      </template>

      <template v-slot:no-data>
        <v-btn disabled>No Projects Found</v-btn>
      </template>
    </v-data-table>

    <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>

    <v-alert v-if="error" type="error">
      Error loading projects: {{ error }}
    </v-alert>

    <!-- Dialog for PasteProjectDetail -->
    <v-dialog v-model="dialog0" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline">Paste 0</span>
        </v-card-title>
        <v-card-text>
          <PasteProjectHeader />
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="closeDialog0">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-dialog v-model="dialog1" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline">Paste 1</span>
        </v-card-title>
        <v-card-text>
          <PasteProjectHdPart1 :projectId="selectedProjectId" />
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="closeDialog1">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-dialog v-model="dialog2" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline2">Paste 2</span>
        </v-card-title>
        <v-card-text>
          <PasteProjectHdPart2 :projectId="selectedProjectId" />
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="closeDialog2">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-dialog v-model="dialog3" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline2">Paste 3</span>
        </v-card-title>
        <v-card-text>
          <PasteProjectHdPart3 :projectId="selectedProjectId" />
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="closeDialog3">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </v-container>
</template>

<script>
import 'vuetify/styles'; // Ensure Vuetify styles are included
import { ref, onMounted } from 'vue';
import { formatNumberWith3LeadingZeros, loadAllProjects, saveProject } from '../utils/contactUtils';
import PasteProjectHdPart3 from './pasteProjectHdPart3.vue';
import PasteProjectHdPart1 from './PasteProjectHdPart1.vue';
import PasteProjectHdPart2 from './PasteProjectHdPart2.vue';
import PasteProjectHeader from './PasteProjectHeader.vue';



export default {
  name: 'ProjectListing',
  components: {
    PasteProjectHdPart3, PasteProjectHdPart1, PasteProjectHdPart2,PasteProjectHeader
  },
  setup() {
    const headers = [
      { text: 'P1' },


      { text: 'No', title: 'No', value: 'no' },
      { text: 'Project Name', title: 'Project Name', value: 'projectName' },
      { text: 'Project Type', title: 'Project Type', value: 'projectType' },
      { text: 'Location', title: 'Location', value: 'location' },
      { text: 'EUM PIC NAME', title: 'EUM PIC NAME', value: 'eumPicName' },
      { text: 'EUM PIC Contact', title: 'EUM PIC Contact', value: 'eumPicContact' },
      { text: 'Branch', title: 'Branch', value: 'branch' },
      { text: 'Agent Comm', title: 'Agent Comm', value: 'agentComm' },
      { text: 'Advance Comm', title: 'Advance Comm', value: 'advanceComm' },

      { text: 'Rebate', title: 'Rebate', value: 'rebate' },
      { text: 'Status', title: 'Status', value: 'status' },
      { text: 'Title', title: 'Title', value: 'title' },
      { text: 'Tenure', title: 'Tenure', value: 'tenure' },
      { text: 'Price Range', title: 'Price Range', value: 'priceRange' },
      { text: 'Size Range', title: 'Size Range', value: 'sizeRange' },


      { text: 'Total Unit', title: 'Total Unit', value: 'totalUnit' },
      { text: 'Total Storey', title: 'Total Storey', value: 'totalStorey' },
      { text: 'Contract Start Date', title: 'Contract Start Date', value: 'contractStartDate' },
      { text: 'Contract End Date', title: 'Contract End Date', value: 'contractEndDate' },

      { text: 'Developer', title: 'Developer', value: 'developer' },
      { text: 'Actions', value: 'actions' }, // Column for the button
      { text: 'Completion Date', title: 'Completion Date', value: 'completionDate' },
      { text: 'ID', title: 'ID', value: 'id' },
    ];

    const projects = ref([]);
    const loading = ref(false);
    const error = ref(null);
    const dialog0 = ref(false); // Control the dialog visibility
    const dialog1 = ref(false); // Control the dialog visibility
    const dialog2 = ref(false); // Control the dialog visibility
    const dialog3 = ref(false);
    const selectedProjectId = ref(null); // Store the selected project ID
    const selectedRow = ref(null); // Track the selected row

    const selectRow = (index) => {
      selectedRow.value = index;
    };
    onMounted(async () => {
      loading.value = true;
      try {
        projects.value = await loadAllProjects();
        console.log(projects.value);
      } catch (err) {
        error.value = err.message || 'Failed to load projects';
        console.error('Error loading projects:', err);
      } finally {
        loading.value = false;
      }
    });

    const openDialog0 = () => {
      dialog0.value = true; // Open the dialog
    };

    const openDialog1 = (id) => {
      selectedProjectId.value = id; // Set the selected project ID
      dialog1.value = true; // Open the dialog
    };


    const openDialog2 = (id) => {
      selectedProjectId.value = id; // Set the selected project ID
      dialog2.value = true; // Open the dialog
    };

    const openDialog3 = (id) => {
      selectedProjectId.value = id; // Set the selected project ID
      dialog3.value = true; // Open the dialog
    };

    const closeDialog0 = () => {
      dialog0.value = false; // Close the dialog
      //     selectedProjectId.value = null; // Reset the selected project ID
    };

    const closeDialog1 = () => {
      dialog1.value = false; // Close the dialog
      //     selectedProjectId.value = null; // Reset the selected project ID
    };

    const closeDialog2 = () => {
      dialog2.value = false; // Close the dialog
      //     selectedProjectId.value = null; // Reset the selected project ID
    };

    const closeDialog3 = () => {
      dialog3.value = false; // Close the dialog
      //     selectedProjectId.value = null; // Reset the selected project ID
    };

    const renumberProjects = async () => {
      // Update "no" field in ascending order and send updates to the server
      for (let i = 0; i < projects.value.length; i++) {


        try {
          await saveProject(projects.value[i].id, formatNumberWith3LeadingZeros(i + 1)); // Assuming saveProject handles updating the server
        } catch (err) {
          console.error(`Failed to update project ${projects.value[i].id}:`, err);
          alert(err.message);
          return
        }
      }
      alert("sort completed");
    };

    return {
      headers,
      projects,
      loading,
      error,
      openDialog0,
      openDialog1,
      openDialog2,
      openDialog3,
      closeDialog0,
      closeDialog1,
      closeDialog2,
      closeDialog3,
      dialog0,
      dialog1,
      dialog2,
      dialog3,
      selectedProjectId,
      renumberProjects,
      selectedRow,
      selectRow,
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}

.elevation-1 {
  min-height: 300px;
}

.odd-row {
  background-color: #e5f5f5;
  /* Light grey background for odd rows */
}

.even-row {
  background-color: #ffffff;
  /* White background for even rows */
}

.small-btn {
  min-width: 40px;
  /* Smaller width for compactness */
  padding: 1px;
  /* Adjust padding */
  font-size: 0.8rem;
  /* Smaller font size */
  margin-right: 1px;
  /* Adjust this to control the space between buttons */
}

.button-container {
  display: flex;
  gap: 2px;
  /* Adjust this to control the space between buttons */
}

.custom-header-table ::v-deep th {
  background-color: #14376d !important;
  color: white !important;
  border-bottom: thin solid rgba(255, 255, 255, 0.12) !important;
}

.custom-header-table ::v-deep .v-data-table__wrapper {
  border: 1px solid #e0e0e0;
}

.highlighted-row {
  background-color: #ffd1ea;
  /* Blue highlight color for selected row */
}
</style>
