<template>
  <div>
    <v-toolbar color="primary" dark>
      <v-toolbar-title>part 3</v-toolbar-title>
    </v-toolbar>


    <v-data-table
      v-model="gridData"
      :headers="headers"
      :items="gridData"
      item-value="id"
      class="elevation-1"
      @paste="handlePaste"
    >
      <template v-slot:no-data>
        <v-btn @click="addRow">Add Header Detail Data</v-btn>
      </template>
    </v-data-table>
    <v-btn @click="exportData">Export Data to Strapi</v-btn>

    <!-- Display the exported array (for demo purposes) -->
    <div v-if="exportedData.length > 0">
      <h3>Exported Data</h3>
      <pre>{{ exportedData }}</pre>
    </div>
  </div>
</template>

<script>
import { ref} from 'vue';
import { updateProjectLayout } from '../utils/contactUtils'; // Import the function to update layout

export default {

  props: {
    projectId: {
      type: String,
      required: true,
    },
  },
  setup(props) {
    // Define the headers based on the new structure
    const headers = [
      { text: 'Project ID', value: 'id' }, // Assuming the first column is the project ID
      { text: 'Type', value: 'type' },
      { text: 'Built Up', value: 'builtUp' },
      { text: 'Bedrooms', value: 'bedroom' },
      { text: 'Bathrooms', value: 'bathroom' },
      { text: 'Carpark', value: 'carpark' },
      { text: 'Has Balcony', value: 'hasBalcony' },
    ];

    const gridData = ref([]); // Holds grid data
    const exportedData = ref([]); // Will hold the exported array data

    // Function to handle pasted data
    const handlePaste = (event) => {
      const clipboardData = event.clipboardData || window.clipboardData;
      let pastedText = clipboardData.getData('text/plain');

      // Replace tabs and newlines with markers, then split into rows
      const rows = pastedText.trim().split('\t\r\n').filter((row) => row.trim() !== '');

      // Process each row and map to the correct columns
      const parsedData = rows.map((row) => {
        const columns = row.split('\t'); // Assuming tab-separated values

        return {
          id: columns[0] || '', // Assuming the first column is the project ID
          type: columns[1] || '',
          builtUp: columns[2] || '',
          bedroom: parseInt(columns[3]) || 0,
          bathroom: parseInt(columns[4]) || 0,
          carpark: parseInt(columns[5]) || 0,
          hasBalcony: columns[6] !== '<< None >>', // Assuming the last column is a boolean
        };
      });

      // Update grid data with parsed data
      gridData.value = [...gridData.value, ...parsedData];
    };

    // Function to add a new row
    const addRow = () => {
      gridData.value.push({
        id: '',
        type: '',
        builtUp: '',
        bedroom: 0,
        bathroom: 0,
        carpark: 0,
        hasBalcony: false,
      });
    };

    // Function to export layout data to Strapi
    const exportData = async () => {

      try {
     
        // Update the layout for each project in the grid data
        let aa = [];
        for (const layout of gridData.value) {
       
          aa.push({
            type: layout.type,
            builtUp: layout.builtUp,
            bedroom: layout.bedroom,
            bathroom: layout.bathroom,
            carpark: layout.carpark,
            hasBalcony: layout.hasBalcony,
          });

         

        }
        await updateProjectLayout(props.projectId, aa);
        exportedData.value = [...gridData.value]; // Copy layout data to exported array
        alert('Layout successfully updated in the project schema!');
      } catch (error) {
        console.error('Error updating layout in project schema:', error);
        alert('Failed to update layout.');
      }
    };

    return {
      headers,
      gridData,
      exportedData,
      handlePaste,
      addRow,
      exportData,
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}
</style>
